changeSet.sql:
insert into reporting_tenant_settings (
    tenant_id, delivery_target_minutes, delivery_target_percent,
    straight_through_target_percent, review_wait_target_minutes, updated_at
)
select id, 240, 95.00, 90.00, 60, now() from tenants
on conflict (tenant_id) do nothing;

create or replace function reporting_capture_package_dimensions(
    p_tenant uuid, p_package uuid, p_business_record uuid
) returns void language plpgsql as $$
begin
    if p_business_record is null then
        return;
    end if;
    insert into reporting_package_dimensions (
        tenant_id, package_id, dimension_key, dimension_label, dimension_value, captured_at
    )
    select p_tenant, p_package, rd.dimension_key, rd.dimension_label,
           bri.identifier_value, now()
      from reporting_dimension_definitions rd
      join business_record_identifiers bri
        on bri.tenant_id=rd.tenant_id and bri.definition_id=rd.definition_id
     where rd.tenant_id=p_tenant and rd.enabled_flag=true
       and bri.business_record_id=p_business_record
    on conflict (tenant_id, package_id, dimension_key) do update set
        dimension_label=excluded.dimension_label,
        dimension_value=excluded.dimension_value;
end $$;

create or replace function reporting_backfill_tenant_dimensions(p_tenant uuid)
returns integer language plpgsql as $$
declare affected integer;
begin
    insert into reporting_package_dimensions (
        tenant_id, package_id, dimension_key, dimension_label, dimension_value, captured_at
    )
    select f.tenant_id, f.package_id, rd.dimension_key, rd.dimension_label,
           bri.identifier_value, now()
      from reporting_package_facts f
      join reporting_dimension_definitions rd
        on rd.tenant_id=f.tenant_id and rd.enabled_flag=true
      join business_record_identifiers bri
        on bri.tenant_id=f.tenant_id and bri.business_record_id=f.business_record_id
       and bri.definition_id=rd.definition_id
     where f.tenant_id=p_tenant and f.business_record_id is not null
    on conflict (tenant_id, package_id, dimension_key) do update set
        dimension_label=excluded.dimension_label,
        dimension_value=excluded.dimension_value;
    get diagnostics affected = row_count;
    return affected;
end $$;

create or replace function reporting_capture_dimension_fact_trigger()
returns trigger language plpgsql as $$
begin
    perform reporting_capture_package_dimensions(new.tenant_id, new.package_id, new.business_record_id);
    return new;
end $$;

drop trigger if exists trg_reporting_package_dimension_capture on reporting_package_facts;
create trigger trg_reporting_package_dimension_capture
after insert or update of business_record_id on reporting_package_facts
for each row execute function reporting_capture_dimension_fact_trigger();

rollback.sql:
drop trigger if exists trg_reporting_package_dimension_capture on reporting_package_facts;
drop function if exists reporting_capture_dimension_fact_trigger();
drop function if exists reporting_backfill_tenant_dimensions(uuid);
drop function if exists reporting_capture_package_dimensions(uuid,uuid,uuid);
